import { Network } from "@/utils/wallet/wallet_provider";
export var network = process.env.VUE_APP_PUBLIC_NETWORK || Network.SIGNET;
var mainnetConfig = {
    coinName: "BTC",
    coinSymbol: "BTC",
    networkName: "BTC",
    mempoolApiUrl: "".concat(process.env.VUE_APP_PUBLIC_MEMPOOL_API),
    network: Network.MAINNET,
};
var signetConfig = {
    coinName: "Signet BTC",
    coinSymbol: "sBTC",
    networkName: "BTC signet",
    mempoolApiUrl: "".concat(process.env.VUE_APP_PUBLIC_MEMPOOL_API, "/signet"),
    network: Network.SIGNET,
};
var testnetConfig = {
    coinName: "Testnet BTC",
    coinSymbol: "tBTC",
    networkName: "BTC testnet",
    mempoolApiUrl: "".concat(process.env.VUE_APP_PUBLIC_MEMPOOL_API, "/testnet"),
    network: Network.TESTNET,
};
var config = {
    mainnet: mainnetConfig,
    signet: signetConfig,
    testnet: testnetConfig,
};
export function getNetworkConfig() {
    switch (network) {
        case Network.MAINNET:
            return config.mainnet;
        case Network.SIGNET:
            return config.signet;
        case Network.TESTNET:
            return config.testnet;
        default:
            return config.signet;
    }
}
export function validateAddress(network, address) {
    if (network === Network.MAINNET && !address.startsWith("bc1")) {
        throw new Error("Incorrect address prefix for Mainnet. Expected address to start with 'bc1'.");
    }
    else if ([Network.SIGNET, Network.TESTNET].includes(network) &&
        !address.startsWith("tb1")) {
        throw new Error("Incorrect address prefix for Testnet / Signet. Expected address to start with 'tb1'.");
    }
    else if (![Network.MAINNET, Network.SIGNET, Network.TESTNET].includes(network)) {
        throw new Error("Unsupported network: ".concat(network, ". Please provide a valid network."));
    }
}
